import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"多束电子束直写","description":"","frontmatter":{"title":"多束电子束直写","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/multibeam-direct-write.md","filePath":"litho/multibeam-direct-write.md","lastUpdated":1789023840000}'),E={name:"litho/multibeam-direct-write.md"};function c(A,a,m,_,u,f){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="多束电子束直写" tabindex="-1">多束电子束直写 <a class="header-anchor" href="#多束电子束直写" aria-label="Permalink to &quot;多束电子束直写&quot;">​</a></h1><div class="epigraph"><p>掩模多束已经量产；晶圆直写仍撞面积×剂量墙。无掩模对逻辑全片是另一道产能物理，不是把写版机放大。</p><footer>—— 对照 MAPPER/IMS 一类晶圆多束直写尝试与掩模多束成功的公开对照</footer></div><p><a href="/litho/3d-nand-litho-shift">上一课</a>结束节点经济课序。缺口是：能否绕过掩模。本课钉多束电子束直写（晶圆）。干涉光刻作为周期图形的另一条路，留给[下一课](/litho/interference-lithography）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/multibeam-mask-writer">多束写掩模</a> 成功，因为 6 寸版面积有限、一张版服务许多晶圆。晶圆直写要把每片都写满，面积大两到三个数量级，即使十万束，wph 仍难跟扫描机比。MAPPER 等项目展示过原理与部分产线故事，量产逻辑全片未取代光学。用途残留：研制、小批量、个性化、修补、对准标记、某些封装。</p><p>缺口是<strong>面积墙</strong>，不是束斑能不能细。把掩模多束的成功直接写成晶圆无掩模量产，单位错了。</p><h3 id="与-pec-的关系" tabindex="-1">与 PEC 的关系 <a class="header-anchor" href="#与-pec-的关系" aria-label="Permalink to &quot;与 PEC 的关系&quot;">​</a></h3><p>晶圆直写仍要电子 PEC，邻近核与衬底有关，和光学 OPC 不同。混合流程（光学粗 + 电子修）是可能工程，不是本课重点。</p><p><span class="marginnote">无掩模的价值在掩模成本摊不薄的时候（样品、多品种），与交叉课的「量大摊销」相反。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较：写时间 ∝ 面积 × 剂量 / 总电流。扫描机：一场光学并行。只有当品种极多、面积极小或分辨率光学达不到时，直写胜。规划不要用直写去填 EUV 槽位缺口——量级不对。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学投影一次性把掩模场印到晶圆；直写是串行（尽管多束并行度高）。并行度必须赶上场像素数才有同等 wph，这正是掩模多束够用、晶圆不够的原因。</p>',13)),(e(),s(p,null,{default:i(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%A4%9A%E6%9D%9F%3A%20%E9%9D%A2%E7%A7%AF%E5%B0%8F%22%5D%20--%3E%20OK%5B%22%E9%87%8F%E4%BA%A7%E5%86%99%E7%89%88%22%5D%0A%20%20WAF%5B%22%E6%99%B6%E5%9C%86%E7%9B%B4%E5%86%99%3A%20%E9%9D%A2%E7%A7%AF%E5%A4%A7%22%5D%20--%3E%20WALL%5B%22wph%20%E5%A2%99%22%5D%0A%20%20WALL%20--%3E%20NICHE%5B%22%E6%A0%B7%E5%93%81%20%2F%20%E5%B0%8F%E6%89%B9%E9%87%8F%20%2F%20%E4%BF%AE%E8%A1%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不宣布直写永远失败。源电流与胶灵敏度的未来改善可能移动墙，仍须过面积算术。不写某已停项目的内部规格。</p><p>后课默认：全片无掩模电子束不是先进逻辑的主路径；下一课干涉法用光子的并行性印周期结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>晶圆多束直写撞面积×剂量墙；掩模多束因面积小而量产。</li><li>适合小批量与研制，不适合填 EUV 产能缺口。</li><li>并行度必须比上场像素数。</li><li>出处：晶圆多束直写与掩模多束的公开对照。</li></ul>',5))])}const B=l(E,[["render",c]]);export{b as __pageData,B as default};
